module EF_TMR32 #(
    parameter PRW = 16,
    PWM_FAULT_CLR_C0 = 16'hA539,
    PWM_FAULT_CLR_C1 = 16'hA953
) (
    input  wire           clk,
    input  wire           rst_n,
    input  wire           tmr_en,
    input  wire           tmr_start,
    input  wire           pwm0_en,
    input  wire           pwm1_en,
    input  wire [31:0]    tmr_reload,
    input  wire [31:0]    cmpx,
    input  wire [31:0]    cmpy,
    input  wire [PRW-1:0] prescaler,
    input  wire [2:0]     tmr_cfg,
    input  wire [11:0]    pwm0_cfg,
    input  wire [11:0]    pwm1_cfg,
    input  wire           pwm0_inv,
    input  wire           pwm1_inv,
    input  wire [7:0]     pwm_dt,
    input  wire [15:0]    pwm_fault_clr,
    input  wire           pwm_dt_en,
    output wire [31:0]    tmr,
    output wire           matchx_flag,
    output wire           matchy_flag,
    output wire           timeout_flag,
    input  wire           pwm_fault,
    output wire           pwm0,
    output wire           pwm1
);

    wire [1:0] mode = tmr_cfg[1:0];
    wire periodic = tmr_cfg[2];

    reg [31:0] tmr_reg;
    reg [PRW-1:0] pr_reg;
    reg tmr_dir;
    reg tmr_run;

    reg te_last;
    wire te_rise = tmr_en & ~te_last;
    wire tick = (pr_reg == {PRW{1'b0}});

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            te_last <= 1'b0;
        else
            te_last <= tmr_en;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pr_reg <= {{(PRW-1){1'b0}}, 1'b1};
        else if (!tmr_en)
            pr_reg <= prescaler;
        else if (tick)
            pr_reg <= prescaler;
        else
            pr_reg <= pr_reg - 1'b1;
    end

    wire eq_reload = (tmr_reg == tmr_reload);
    wire eq_zero   = (tmr_reg == 32'd0);
    wire eq_cmpx   = (tmr_reg == cmpx);
    wire eq_cmpy   = (tmr_reg == cmpy);
    wire eq_reload_m1 = (tmr_reg == (tmr_reload - 32'd1));
    wire eq_one = (tmr_reg == 32'd1);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tmr_reg <= 32'd0;
            tmr_dir <= 1'b1;
            tmr_run <= 1'b0;
        end else begin
            if (te_rise) begin
                tmr_run <= 1'b1;
                if (mode == 2'b01) begin
                    tmr_reg <= tmr_reload;
                    tmr_dir <= 1'b0;
                end else begin
                    tmr_reg <= 32'd0;
                    tmr_dir <= 1'b1;
                end
            end else begin
                if (tick) begin
                    if (mode == 2'b11) begin
                        if (tmr_dir && eq_reload_m1)
                            tmr_dir <= 1'b0;
                        else if (!tmr_dir && eq_one)
                            tmr_dir <= 1'b1;
                    end else if (mode == 2'b01) begin
                        tmr_dir <= 1'b0;
                    end else begin
                        tmr_dir <= 1'b1;
                    end

                    if (tmr_en && tmr_run) begin
                        if (tmr_start && (mode == 2'b01)) begin
                            tmr_reg <= tmr_reload;
                        end else if (tmr_start &&
                                     ((mode == 2'b10) || (mode == 2'b11))) begin
                            tmr_reg <= 32'd0;
                        end else begin
                            case (mode)
                                2'b11: begin
                                    if (tmr_dir)
                                        tmr_reg <= tmr_reg + 1'b1;
                                    else
                                        tmr_reg <= tmr_reg - 1'b1;
                                end

                                2'b01: begin
                                    if (eq_zero) begin
                                        if (periodic)
                                            tmr_reg <= tmr_reload;
                                    end else begin
                                        tmr_reg <= tmr_reg - 1'b1;
                                    end
                                end

                                2'b10: begin
                                    if (eq_reload) begin
                                        if (periodic)
                                            tmr_reg <= 32'd0;
                                    end else begin
                                        tmr_reg <= tmr_reg + 1'b1;
                                    end
                                end

                                default: begin
                                    tmr_reg <= tmr_reg;
                                end
                            endcase
                        end

                        if (!periodic && mode[0] && !tmr_dir && eq_one)
                            tmr_run <= 1'b0;
                    end
                end
            end
        end
    end

    function [0:0] pwm_action;
        input [1:0] action;
        input       current;
        begin
            case (action)
                2'b00: pwm_action = current;
                2'b01: pwm_action = 1'b0;
                2'b10: pwm_action = 1'b1;
                default: pwm_action = ~current;
            endcase
        end
    endfunction

    reg pwm0_reg;
    reg pwm1_reg;
    reg pwm0_next;
    reg pwm1_next;

    always @* begin
        pwm0_next = pwm0_reg;
        if (eq_zero && !eq_cmpx && !eq_cmpy && !eq_reload)
            pwm0_next = pwm_action(pwm0_cfg[1:0], pwm0_reg);
        else if (tmr_dir && eq_cmpx && !eq_zero && !eq_cmpy && !eq_reload)
            pwm0_next = pwm_action(pwm0_cfg[3:2], pwm0_reg);
        else if (tmr_dir && eq_cmpy && !eq_zero && !eq_cmpx && !eq_reload)
            pwm0_next = pwm_action(pwm0_cfg[5:4], pwm0_reg);
        else if (eq_reload && !eq_zero && !eq_cmpx && !eq_cmpy)
            pwm0_next = pwm_action(pwm0_cfg[7:6], pwm0_reg);
        else if (!tmr_dir && eq_cmpy && !eq_zero && !eq_cmpx && !eq_reload)
            pwm0_next = pwm_action(pwm0_cfg[9:8], pwm0_reg);
        else if (!tmr_dir && eq_cmpx && !eq_zero && !eq_cmpy && !eq_reload)
            pwm0_next = pwm_action(pwm0_cfg[11:10], pwm0_reg);
    end

    always @* begin
        pwm1_next = pwm1_reg;
        if (eq_zero && !eq_cmpx && !eq_cmpy && !eq_reload)
            pwm1_next = pwm_action(pwm1_cfg[1:0], pwm1_reg);
        else if (tmr_dir && eq_cmpx && !eq_zero && !eq_cmpy && !eq_reload)
            pwm1_next = pwm_action(pwm1_cfg[3:2], pwm1_reg);
        else if (tmr_dir && eq_cmpy && !eq_zero && !eq_cmpx && !eq_reload)
            pwm1_next = pwm_action(pwm1_cfg[5:4], pwm1_reg);
        else if (eq_reload && !eq_zero && !eq_cmpx && !eq_cmpy)
            pwm1_next = pwm_action(pwm1_cfg[7:6], pwm1_reg);
        else if (!tmr_dir && eq_cmpy && !eq_zero && !eq_cmpx && !eq_reload)
            pwm1_next = pwm_action(pwm1_cfg[9:8], pwm1_reg);
        else if (!tmr_dir && eq_cmpx && !eq_zero && !eq_cmpy && !eq_reload)
            pwm1_next = pwm_action(pwm1_cfg[11:10], pwm1_reg);
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pwm0_reg <= 1'b0;
            pwm1_reg <= 1'b0;
        end else if (tick && pwm0_en) begin
            if (pwm_fault)
                pwm0_reg <= 1'b0;
            else
                pwm0_reg <= pwm0_next;
        end else if (tick && pwm1_en && pwm_fault) begin
            pwm1_reg <= 1'b0;
        end

        if (rst_n && tick && pwm1_en && !pwm_fault)
            pwm1_reg <= pwm1_next;
    end

    reg [7:0] dead_count;
    reg pwm0_delayed;
    reg pwm0_out_reg;
    reg pwm1_out_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dead_count   <= 8'd0;
            pwm0_delayed <= 1'b0;
        end else if (tick) begin
            if (dead_count == 8'd0) begin
                dead_count   <= pwm_dt;
                pwm0_delayed <= pwm0_reg;
            end else begin
                dead_count <= dead_count - 1'b1;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pwm0_out_reg <= 1'b0;
            pwm1_out_reg <= 1'b0;
        end else if (pwm_dt_en) begin
            pwm0_out_reg <= pwm0_delayed & pwm0_reg;
            pwm1_out_reg <= ~pwm0_delayed & ~pwm0_reg;
        end else begin
            pwm0_out_reg <= pwm0_reg;
            pwm1_out_reg <= pwm1_reg;
        end
    end

    reg fault_armed;
    reg fault_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            fault_armed <= 1'b0;
        else if (pwm_fault_clr == PWM_FAULT_CLR_C0)
            fault_armed <= 1'b1;
        else if (pwm_fault_clr == PWM_FAULT_CLR_C1)
            fault_armed <= 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            fault_reg <= 1'b0;
        else if (pwm_fault)
            fault_reg <= 1'b1;
