                                    if (eq_zero) begin
                                        if (periodic)
                                            tmr_reg <= tmr_reload;
                                    end else begin
                                        tmr_reg <= tmr_reg - 1'b1;
                                    end
                                end

                                2'b10: begin
                                    if (eq_reload) begin
                                        if (periodic)
                                            tmr_reg <= 32'd0;
                                    end else begin
                                        tmr_reg <= tmr_reg + 1'b1;
                                    end
                                end

                                default: begin
                                    tmr_reg <= tmr_reg;
                                end
                            endcase
                        end

                        if (!periodic && mode[0] && !tmr_dir && eq_one)
                            tmr_run <= 1'b0;
                    end
                end
            end
        end
    end

    function [0:0] pwm_action;
        input [1:0] action;
        input       current;
        begin
            case (action)
                2'b00: pwm_action = current;
                2'b01: pwm_action = 1'b0;
                2'b10: pwm_action = 1'b1;
                default: pwm_action = ~current;
            endcase
        end
    endfunction

    reg pwm0_reg;
    reg pwm1_reg;
    reg pwm0_next;
    reg pwm1_next;

    always @* begin
        pwm0_next = pwm0_reg;
        if (eq_zero && !eq_cmpx && !eq_cmpy && !eq_reload)
            pwm0_next = pwm_action(pwm0_cfg[1:0], pwm0_reg);
        else if (tmr_dir && eq_cmpx && !eq_zero && !eq_cmpy && !eq_reload)
            pwm0_next = pwm_action(pwm0_cfg[3:2], pwm0_reg);
        else if (tmr_dir && eq_cmpy && !eq_zero && !eq_cmpx && !eq_reload)
            pwm0_next = pwm_action(pwm0_cfg[5:4], pwm0_reg);
        else if (eq_reload && !eq_zero && !eq_cmpx && !eq_cmpy)
            pwm0_next = pwm_action(pwm0_cfg[7:6], pwm0_reg);
        else if (!tmr_dir && eq_cmpy && !eq_zero && !eq_cmpx && !eq_reload)
            pwm0_next = pwm_action(pwm0_cfg[9:8], pwm0_reg);
        else if (!tmr_dir && eq_cmpx && !eq_zero && !eq_cmpy && !eq_reload)
            pwm0_next = pwm_action(pwm0_cfg[11:10], pwm0_reg);
    end

    always @* begin
        pwm1_next = pwm1_reg;
        if (eq_zero && !eq_cmpx && !eq_cmpy && !eq_reload)
            pwm1_next = pwm_action(pwm1_cfg[1:0], pwm1_reg);
        else if (tmr_dir && eq_cmpx && !eq_zero && !eq_cmpy && !eq_reload)
            pwm1_next = pwm_action(pwm1_cfg[3:2], pwm1_reg);
        else if (tmr_dir && eq_cmpy && !eq_zero && !eq_cmpx && !eq_reload)
            pwm1_next = pwm_action(pwm1_cfg[5:4], pwm1_reg);
        else if (eq_reload && !eq_zero && !eq_cmpx && !eq_cmpy)
            pwm1_next = pwm_action(pwm1_cfg[7:6], pwm1_reg);
        else if (!tmr_dir && eq_cmpy && !eq_zero && !eq_cmpx && !eq_reload)
            pwm1_next = pwm_action(pwm1_cfg[9:8], pwm1_reg);
        else if (!tmr_dir && eq_cmpx && !eq_zero && !eq_cmpy && !eq_reload)
            pwm1_next = pwm_action(pwm1_cfg[11:10], pwm1_reg);
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pwm0_reg <= 1'b0;
            pwm1_reg <= 1'b0;
        end else if (tick && pwm0_en) begin
            if (pwm_fault)
                pwm0_reg <= 1'b0;
            else
                pwm0_reg <= pwm0_next;
        end else if (tick && pwm1_en && pwm_fault) begin
            pwm1_reg <= 1'b0;
        end

        if (rst_n && tick && pwm1_en && !pwm_fault)
            pwm1_reg <= pwm1_next;
    end

    reg [7:0] dead_count;
    reg pwm0_delayed;
    reg pwm0_out_reg;
    reg pwm1_out_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dead_count   <= 8'd0;
            pwm0_delayed <= 1'b0;
        end else if (tick) begin
            if (dead_count == 8'd0) begin
                dead_count   <= pwm_dt;
                pwm0_delayed <= pwm0_reg;
            end else begin
                dead_count <= dead_count - 1'b1;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pwm0_out_reg <= 1'b0;
            pwm1_out_reg <= 1'b0;
        end else if (pwm_dt_en) begin
            pwm0_out_reg <= pwm0_delayed & pwm0_reg;
            pwm1_out_reg <= ~pwm0_delayed & ~pwm0_reg;
        end else begin
            pwm0_out_reg <= pwm0_reg;
            pwm1_out_reg <= pwm1_reg;
        end
    end

    reg fault_armed;
    reg fault_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            fault_armed <= 1'b0;
        else if (pwm_fault_clr == PWM_FAULT_CLR_C0)
            fault_armed <= 1'b1;
        else if (pwm_fault_clr == PWM_FAULT_CLR_C1)
            fault_armed <= 1'b0;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            fault_reg <= 1'b0;
        else if (pwm_fault)
            fault_reg <= 1'b1;
        else if (fault_armed && (pwm_fault_clr == PWM_FAULT_CLR_C1))
            fault_reg <= 1'b0;
    end

    assign tmr = tmr_reg;
    assign matchx_flag = eq_cmpx;
    assign matchy_flag = eq_cmpy;
    assign timeout_flag = tmr_dir ? eq_reload : eq_zero;

    assign pwm0 = (pwm0_out_reg ^ pwm0_inv) & ~fault_reg & pwm0_en;
    assign pwm1 = (pwm1_out_reg ^ pwm1_inv) & ~fault_reg & pwm1_en;

endmodule

module EF_TMR32_APB #(
    parameter PRW = 16
) (
    input  wire         PCLK,
    input  wire         PRESETn,
    input  wire         PWRITE,
    input  wire [31:0]  PWDATA,
    input  wire [31:0]  PADDR,
    input  wire         PENABLE,
    input  wire         PSEL,
    output wire         PREADY,
    output wire [31:0]  PRDATA,
    output wire         IRQ,
    output wire [1-1:0] pwm0,
    output wire [1-1:0] pwm1,
    input  wire [1-1:0] pwm_fault
);

    localparam TMR_REG_OFFSET    = 16'h0000;
    localparam RELOAD_REG_OFFSET = 16'h0004;
    localparam PR_REG_OFFSET     = 16'h0008;
    localparam CMPX_REG_OFFSET   = 16'h000C;
    localparam CMPY_REG_OFFSET   = 16'h0010;
    localparam CTRL_REG_OFFSET   = 16'h0014;
    localparam CFG_REG_OFFSET    = 16'h0018;
    localparam PWM0CFG_REG_OFFSET = 16'h001C;
    localparam PWM1CFG_REG_OFFSET = 16'h0020;
    localparam PWMDT_REG_OFFSET  = 16'h0024;
    localparam PWMFC_REG_OFFSET  = 16'h0028;
    localparam IM_REG_OFFSET     = 16'hFF00;
    localparam MIS_REG_OFFSET    = 16'hFF04;
    localparam RIS_REG_OFFSET    = 16'hFF08;
    localparam IC_REG_OFFSET     = 16'hFF0C;
    localparam GCLK_REG_OFFSET   = 16'hFF10;

    wire apb_valid = PSEL & PENABLE;
    wire apb_we = apb_valid & PWRITE;

    reg [31:0] RELOAD_REG;
    reg [PRW-1:0] PR_REG;
    reg [31:0] CMPX_REG;
    reg [31:0] CMPY_REG;
    reg [6:0] CTRL_REG;
    reg [2:0] CFG_REG;
    reg [11:0] PWM0CFG_REG;
    reg [15:0] PWM1CFG_REG;
    reg [7:0] PWMDT_REG;
    reg [15:0] PWMFC_REG;
    reg GCLK_REG;

    reg [2:0] IM_REG;
    reg [2:0] IC_REG;
    reg [2:0] RIS_REG;

    wire [31:0] tmr;
    wire matchx_flag;
    wire matchy_flag;
    wire timeout_flag;

    wire [2:0] MIS_REG = RIS_REG & IM_REG;

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            RELOAD_REG  <= 32'd0;
            PR_REG      <= {PRW{1'b0}};
            CMPX_REG    <= 32'd0;
            CMPY_REG    <= 32'd0;
            CTRL_REG    <= 7'd0;
            CFG_REG     <= 3'd0;
            PWM0CFG_REG <= 12'd0;
            PWM1CFG_REG <= 16'd0;
            PWMDT_REG   <= 8'd0;
            PWMFC_REG   <= 16'd0;
            GCLK_REG    <= 1'b0;
            IM_REG      <= 3'd0;
            IC_REG      <= 3'd0;
        end else begin
            if (apb_we && PADDR[15:0] == RELOAD_REG_OFFSET)
                RELOAD_REG <= PWDATA;
            if (apb_we && PADDR[15:0] == PR_REG_OFFSET)
                PR_REG <= PWDATA[PRW-1:0];
            if (apb_we && PADDR[15:0] == CMPX_REG_OFFSET)
                CMPX_REG <= PWDATA;
            if (apb_we && PADDR[15:0] == CMPY_REG_OFFSET)
                CMPY_REG <= PWDATA;
            if (apb_we && PADDR[15:0] == CTRL_REG_OFFSET)
                CTRL_REG <= PWDATA[6:0];
            if (apb_we && PADDR[15:0] == CFG_REG_OFFSET)
                CFG_REG <= PWDATA[2:0];
            if (apb_we && PADDR[15:0] == PWM0CFG_REG_OFFSET)
                PWM0CFG_REG <= PWDATA[11:0];
            if (apb_we && PADDR[15:0] == PWM1CFG_REG_OFFSET)
                PWM1CFG_REG <= PWDATA[15:0];
            if (apb_we && PADDR[15:0] == PWMDT_REG_OFFSET)
                PWMDT_REG <= PWDATA[7:0];
            if (apb_we && PADDR[15:0] == PWMFC_REG_OFFSET)
                PWMFC_REG <= PWDATA[15:0];
            if (apb_we && PADDR[15:0] == GCLK_REG_OFFSET)
                GCLK_REG <= PWDATA[0];

            if (apb_we && PADDR[15:0] == IM_REG_OFFSET)
                IM_REG <= PWDATA[2:0];

            if (apb_we && PADDR[15:0] == IC_REG_OFFSET)
                IC_REG <= PWDATA[2:0];
            else
                IC_REG <= 3'd0;
        end
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            RIS_REG <= 3'd0;
        else begin
            if (IC_REG[0])
                RIS_REG[0] <= 1'b0;
            else if (timeout_flag)
                RIS_REG[0] <= 1'b1;

            if (IC_REG[1])
                RIS_REG[1] <= 1'b0;
            else if (matchx_flag)
                RIS_REG[1] <= 1'b1;

            if (IC_REG[2])
                RIS_REG[2] <= 1'b0;
            else if (matchy_flag)
                RIS_REG[2] <= 1'b1;
        end
    end

    EF_TMR32 #(
        .PRW(PRW)
    ) instance_to_wrap (
        .clk(PCLK),
        .rst_n(PRESETn),
        .tmr_en(CTRL_REG[0]),
        .tmr_start(CTRL_REG[1]),
        .pwm0_en(CTRL_REG[2]),
        .pwm1_en(CTRL_REG[3]),
        .tmr_reload(RELOAD_REG),
        .cmpx(CMPX_REG),
        .cmpy(CMPY_REG),
        .prescaler(PR_REG),
        .tmr_cfg(CFG_REG),
        .pwm0_cfg(PWM0CFG_REG),
        .pwm1_cfg(PWM1CFG_REG[11:0]),
        .pwm0_inv(CTRL_REG[5]),
        .pwm1_inv(CTRL_REG[6]),
        .pwm_dt(PWMDT_REG),
        .pwm_fault_clr(PWMFC_REG),
        .pwm_dt_en(CTRL_REG[4]),
        .tmr(tmr),
        .matchx_flag(matchx_flag),
        .matchy_flag(matchy_flag),
        .timeout_flag(timeout_flag),
        .pwm_fault(pwm_fault),
        .pwm0(pwm0),
        .pwm1(pwm1)
    );

    assign PRDATA =
        (PADDR[15:0] == TMR_REG_OFFSET)     ? tmr :
        (PADDR[15:0] == RELOAD_REG_OFFSET)  ? RELOAD_REG :
        (PADDR[15:0] == PR_REG_OFFSET)      ? {{(32-PRW){1'b0}}, PR_REG} :
        (PADDR[15:0] == CMPX_REG_OFFSET)    ? CMPX_REG :
        (PADDR[15:0] == CMPY_REG_OFFSET)    ? CMPY_REG :
        (PADDR[15:0] == CTRL_REG_OFFSET)    ? {{25{1'b0}}, CTRL_REG} :
        (PADDR[15:0] == CFG_REG_OFFSET)     ? {{29{1'b0}}, CFG_REG} :
        (PADDR[15:0] == PWM0CFG_REG_OFFSET) ? {{20{1'b0}}, PWM0CFG_REG} :
        (PADDR[15:0] == PWM1CFG_REG_OFFSET) ? {{16{1'b0}}, PWM1CFG_REG} :
        (PADDR[15:0] == PWMDT_REG_OFFSET)   ? {{24{1'b0}}, PWMDT_REG} :
        (PADDR[15:0] == PWMFC_REG_OFFSET)   ? {{16{1'b0}}, PWMFC_REG} :
        (PADDR[15:0] == IM_REG_OFFSET)      ? {{29{1'b0}}, IM_REG} :
        (PADDR[15:0] == MIS_REG_OFFSET)     ? {{29{1'b0}}, MIS_REG} :
        (PADDR[15:0] == RIS_REG_OFFSET)     ? {{29{1'b0}}, RIS_REG} :
        (PADDR[15:0] == GCLK_REG_OFFSET)    ? {{31{1'b0}}, GCLK_REG} :
        32'hDEADBEEF;

    assign PREADY = 1'b1;
    assign IRQ = |MIS_REG;

endmodule

