         3'b001: tx_next=~^pdata;
         3'b010: tx_next=^pdata;
         3'b100: tx_next=1'b0;
         3'b101: tx_next=1'b1;
       endcase
       if(b_tick)
         if(b_reg==(NUM_SAMPLES-1)) begin
           b_next=0;next_state=stop0_st;
         end else b_next=b_reg+1'b1;
     end
     stop0_st: begin
       tx_next=1'b1;
       if(b_tick)
         if(b_reg==(NUM_SAMPLES-1)) begin
           b_next=0;
           if(stop_bits_count) next_state=stop1_st;
           else begin next_state=idle_st;tx_done=1'b1;end
         end else b_next=b_reg+1'b1;
     end
     stop1_st: begin
       tx_next=1'b1;
       if(b_tick)
         if(b_reg==(NUM_SAMPLES-1)) begin
