   if(!rst_n) begin bits_count<=0;samples_count<=0; end
   else if(b_tick)
     if(rx_done) bits_count<=0;
     else if(samples_count==(SC-1)) begin
       samples_count<=0;
       if(timeout_flag) bits_count<=0;
