module UART_RX #(parameter NUM_SAMPLES=16,MDW=8)(
 input wire clk,input wire resetn,input wire b_tick,
 input wire [3:0] data_size,input wire stop_bits_count,
 input wire [2:0] parity_type,input wire rx,input wire [MDW-1:0] match_data,
 output reg rx_done,output wire parity_error,output wire frame_error,
 output wire break_flag,output wire match_flag,output wire [MDW-1:0] dout);

 localparam [2:0] idle_st=3'b000,start_st=3'b001,data_st=3'b010,
                  parity_st=3'b011,stop0_st=3'b100,stop1_st=3'b101;
 reg [2:0] current_state,next_state;
 reg [3:0] b_reg,b_next,count_reg,count_next;
 reg [8:0] data_reg,data_next;
 reg p_error_reg,p_error_next,f_error_reg,f_error_next;

 always @(posedge clk or negedge resetn)
   if(!resetn) begin
     current_state<=idle_st;b_reg<=0;count_reg<=0;data_reg<=0;
     p_error_reg<=0;f_error_reg<=0;
   end else begin
     current_state<=next_state;b_reg<=b_next;count_reg<=count_next;
     data_reg<=data_next;
     if(current_state==idle_st) p_error_reg<=0;
     else if(p_error_next) p_error_reg<=p_error_next;
     if(current_state==idle_st) f_error_reg<=0;
     else if(f_error_next) f_error_reg<=f_error_next;
   end

 always @* begin
   next_state=current_state;b_next=b_reg;count_next=count_reg;
   data_next=data_reg;rx_done=1'b0;p_error_next=1'b0;f_error_next=1'b0;
   case(current_state)
     idle_st:
       if(~rx&b_tick) begin next_state=start_st;b_next=0;end
     start_st:
       if(b_tick)
         if(b_reg==(NUM_SAMPLES/2-1)) begin
           next_state=data_st;b_next=0;count_next=0;
         end else b_next=b_reg+1'b1;
     data_st:
       if(b_tick)
         if(b_reg==(NUM_SAMPLES-1)) begin
           b_next=0;
           data_next={rx,data_reg[(MDW-1):1]};
           if(count_next==(data_size-1))
             if(parity_type==3'b000) next_state=stop0_st;
             else next_state=parity_st;
           else count_next=count_reg+1'b1;
         end else b_next=b_reg+1'b1;
     parity_st:
       if(b_tick)
         if(b_reg==(NUM_SAMPLES-1)) begin
           b_next=0;next_state=stop0_st;
           case(parity_type)
             3'b001: if((~^dout)!=rx) p_error_next=1'b1;
             3'b010: if((^dout)!=rx) p_error_next=1'b1;
             3'b100: if(1'b0!=rx) p_error_next=1'b1;
             3'b101: if(1'b1!=rx) p_error_next=1'b1;
           endcase
         end else b_next=b_reg+1'b1;
     stop0_st:
       if(b_tick)
         if(b_reg==(NUM_SAMPLES-1)) begin
           b_next=0;
           if(stop_bits_count)
             next_state=stop1_st;
           else begin
             next_state=idle_st;
             rx_done=1'b1;
             if(!rx) f_error_next=1'b1;
           end
         end else b_next=b_reg+1'b1;
     stop1_st:
       if(b_tick)
         if(b_reg==(NUM_SAMPLES-1)) begin
           b_next=0;next_state=idle_st;rx_done=1'b1;
           if(!rx) f_error_next=1'b1;
         end else b_next=b_reg+1'b1;
   endcase
 end

 reg [11:0] brk;
 always @(posedge clk or negedge resetn)
   if(!resetn) brk<=12'hfff;
   else if(b_tick)
     if(b_reg==(NUM_SAMPLES-1))
       if(current_state==idle_st) brk<=12'hfff;
       else brk<={brk[10:0],rx};

 assign dout=data_reg>>(9-data_size);
 assign parity_error=p_error_reg&rx_done;
 assign frame_error=f_error_reg&rx_done;
 assign break_flag=(brk==0);
 assign match_flag=(match_data==dout)&rx_done;
endmodule

module UART_TX #(parameter NUM_SAMPLES=16,MDW=8)(
 input wire clk,input wire resetn,input wire tx_start,input wire b_tick,
 input wire [3:0] data_size,input wire stop_bits_count,
 input wire [2:0] parity_type,input wire [MDW-1:0] d_in,
 output reg tx_done,output wire tx);

 localparam [2:0] idle_st=3'b000,start_st=3'b001,data_st=3'b010,
                  parity_st=3'b011,stop0_st=3'b100,stop1_st=3'b101;
 reg [2:0] current_state,next_state;
 reg [3:0] b_reg,b_next,count_reg,count_next;
 reg [8:0] data_reg,data_next;
 reg tx_reg,tx_next;
 wire [MDW-1:0] pdata=d_in&~({MDW{1'b1}}<<data_size);

 always @(posedge clk or negedge resetn)
   if(!resetn) begin
     current_state<=idle_st;b_reg<=0;count_reg<=0;
     data_reg<=0;tx_reg<=1'b1;
   end else begin
     current_state<=next_state;b_reg<=b_next;count_reg<=count_next;
     data_reg<=data_next;tx_reg<=tx_next;
   end

 always @* begin
   next_state=current_state;tx_done=1'b0;b_next=b_reg;
   count_next=count_reg;data_next=data_reg;tx_next=tx_reg;
   case(current_state)
     idle_st: begin
       tx_next=1'b1;
       if(tx_start) begin next_state=start_st;b_next=0;data_next=d_in;end
     end
     start_st: begin
       tx_next=1'b0;
       if(b_tick)
         if(b_reg==NUM_SAMPLES) begin
           next_state=data_st;b_next=0;count_next=0;
         end else b_next=b_reg+1'b1;
     end
     data_st: begin
       tx_next=data_reg[0];
       if(b_tick)
         if(b_reg==(NUM_SAMPLES-1)) begin
           b_next=0;data_next=data_reg>>1;
           if(count_next==(data_size-1))
             if(parity_type==3'b000) next_state=stop0_st;
             else next_state=parity_st;
           else count_next=count_reg+1'b1;
         end else b_next=b_reg+1'b1;
     end
     parity_st: begin
       tx_next=1'b0;
       case(parity_type)
         3'b001: tx_next=~^pdata;
         3'b010: tx_next=^pdata;
         3'b100: tx_next=1'b0;
         3'b101: tx_next=1'b1;
       endcase
       if(b_tick)
         if(b_reg==(NUM_SAMPLES-1)) begin
           b_next=0;next_state=stop0_st;
         end else b_next=b_reg+1'b1;
     end
     stop0_st: begin
       tx_next=1'b1;
       if(b_tick)
         if(b_reg==(NUM_SAMPLES-1)) begin
           b_next=0;
           if(stop_bits_count) next_state=stop1_st;
           else begin next_state=idle_st;tx_done=1'b1;end
         end else b_next=b_reg+1'b1;
     end
     stop1_st: begin
       tx_next=1'b1;
       if(b_tick)
         if(b_reg==(NUM_SAMPLES-1)) begin
           b_next=0;next_state=idle_st;tx_done=1'b1;
         end else b_next=b_reg+1'b1;
     end
   endcase
 end
 assign tx=tx_reg;
endmodule

