module ef_util_fifo #(parameter DW=8, AW=4) (
    input wire clk, input wire rst_n,
    input wire rd, input wire wr, input wire flush,
    input wire [DW-1:0] wdata,
    output wire empty, output wire full,
    output wire [DW-1:0] rdata,
    output wire [AW-1:0] level
);
    localparam DEPTH = 1 << AW;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] rptr, wptr;
    reg [AW-1:0] level_reg;
    reg full_reg, empty_reg;
    wire do_wr = wr && !full_reg;
    wire do_rd = rd && !empty_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rptr <= 'b0;
            wptr <= 'b0;
            level_reg <= 'b0;
            full_reg <= 1'b0;
            empty_reg <= 1'b1;
        end else if (flush) begin
            rptr <= 'b0;
            wptr <= 'b0;
            level_reg <= 'b0;
            full_reg <= 1'b0;
            empty_reg <= 1'b1;
        end else begin
            if (do_wr) begin
                mem[wptr] <= wdata;
                wptr <= wptr + 1'b1;
            end
            if (do_rd)
                rptr <= rptr + 1'b1;

            case ({do_wr,do_rd})
                2'b10: level_reg <= level_reg + 1'b1;
                2'b01: level_reg <= level_reg - 1'b1;
                default: level_reg <= level_reg;
            endcase

            case ({do_wr,do_rd})
                2'b10: begin
                    empty_reg <= 1'b0;
                    if ((wptr + 1'b1) == rptr)
                        full_reg <= 1'b1;
                end
                2'b01: begin
                    full_reg <= 1'b0;
                    if ((rptr + 1'b1) == wptr)
                        empty_reg <= 1'b1;
                end
                default: begin
                    if (do_wr && do_rd) begin
                        empty_reg <= empty_reg;
                        full_reg <= full_reg;
                    end
                end
            endcase
        end
    end

    assign rdata = mem[rptr];
    assign empty = empty_reg;
    assign full = full_reg;
    assign level = level_reg;
endmodule

module ef_util_gating_cell (
`ifdef USE_POWER_PINS
    input wire vpwr, input wire vgnd,
`endif
    input wire clk, input wire rst_n, input wire clk_en,
    output wire clk_o
);
    assign clk_o = clk;
endmodule

module BAUDGEN (
    input wire clk, input wire rst_n,
    input wire [15:0] prescale, input wire en,
    output wire baudtick
);
    reg [15:0] count_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            count_reg <= 16'b0;
        else if (en)
            count_reg <= (count_reg == prescale) ? 16'b0 : count_reg + 1'b1;
    end

    assign baudtick = en && (count_reg == prescale);
endmodule

module UART_TX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn,
    input wire tx_start, input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [MDW-1:0] d_in,
    output reg tx_done,
    output wire tx
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
                 PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state;
    reg [15:0] sample_count;
    reg [3:0] bit_count;
    reg [MDW-1:0] data_reg;
    reg tx_reg;

    wire parity_value =
        (parity_type == 3'b001) ? ~^data_reg :
        (parity_type == 3'b010) ?  ^data_reg :
        (parity_type == 3'b100) ? 1'b0 :
        (parity_type == 3'b101) ? 1'b1 : 1'b1;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            tx_reg <= 1'b1;
            tx_done <= 1'b0;
        end else begin
            tx_done <= 1'b0;
            case (state)
                IDLE: begin
                    tx_reg <= 1'b1;
                    sample_count <= 0;
                    if (tx_start) begin
                        state <= START;
                        data_reg <= d_in;
                        tx_reg <= 1'b0;
                    end
                end

                START: begin
                    tx_reg <= 1'b0;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES) begin
                            sample_count <= 0;
                            bit_count <= 0;
                            state <= DATA;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                DATA: begin
                    tx_reg <= data_reg[0];
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            data_reg <= data_reg >> 1;
                            if (bit_count == data_size-1) begin
                                state <= (parity_type == 3'b000) ? STOP0 : PARITY;
                            end else
                                bit_count <= bit_count + 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                PARITY: begin
                    tx_reg <= parity_value;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            state <= STOP0;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                STOP0: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            if (stop_bits_count)
                                state <= STOP1;
                            else begin
                                state <= IDLE;
                                tx_done <= 1'b1;
                            end
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                STOP1: begin
                    tx_reg <= 1'b1;
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            state <= IDLE;
                            tx_done <= 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

    assign tx = tx_reg;
endmodule

module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn,
    input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
                 PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state;
    reg [15:0] sample_count;
    reg [3:0] bit_count;
    reg [MDW-1:0] data_reg;
    reg parity_error_reg, frame_error_reg;
    reg [11:0] break_shift;

    wire expected_parity =
        (parity_type == 3'b001) ? ~^data_reg :
        (parity_type == 3'b010) ?  ^data_reg :
        (parity_type == 3'b100) ? 1'b0 :
        (parity_type == 3'b101) ? 1'b1 : 1'b0;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data_reg <= 0;
            parity_error_reg <= 1'b0;
            frame_error_reg <= 1'b0;
            break_shift <= 12'hfff;
            rx_done <= 1'b0;
        end else begin
            rx_done <= 1'b0;

            if (b_tick && (sample_count == NUM_SAMPLES-1)) begin
                if (state == IDLE)
                    break_shift <= 12'hfff;
                else
                    break_shift <= {break_shift[10:0], rx};
            end

            case (state)
                IDLE: begin
                    sample_count <= 0;
                    parity_error_reg <= 1'b0;
                    frame_error_reg <= 1'b0;
                    if (b_tick && !rx)
                        state <= START;
                end

                START: begin
                    if (b_tick) begin
                        if (sample_count == (NUM_SAMPLES/2)-1) begin
                            sample_count <= 0;
                            bit_count <= 0;
                            state <= DATA;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                DATA: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            data_reg[bit_count] <= rx;
                            if (bit_count == data_size-1)
                                state <= (parity_type == 3'b000) ? STOP0 : PARITY;
                            else
                                bit_count <= bit_count + 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                PARITY: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            parity_error_reg <= (rx != expected_parity);
                            state <= STOP0;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                STOP0: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            frame_error_reg <= !rx;
                            if (stop_bits_count)
                                state <= STOP1;
                            else begin
                                state <= IDLE;
                                rx_done <= 1'b1;
                            end
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                STOP1: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            frame_error_reg <= frame_error_reg | !rx;
                            state <= IDLE;
                            rx_done <= 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

    assign dout = data_reg;
    assign parity_error = parity_error_reg && rx_done;
    assign frame_error = frame_error_reg && rx_done;
    assign match_flag = (data_reg == match_data) && rx_done;
    assign break_flag = (break_shift == 12'b0);
endmodule

module EF_UART #(
    parameter MDW=9, FAW=4, SC=8, GFLEN=8
) (
    input wire clk, input wire rst_n,
    input wire [15:0] prescaler,
    input wire en, input wire tx_en, input wire rx_en,
    input wire rd, input wire wr,
    input wire [MDW-1:0] wdata,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [3:0] txfifotr, input wire [3:0] rxfifotr,
    input wire [MDW-1:0] match_data,
    input wire [5:0] timeout_bits,
    input wire loopback_en, input wire glitch_filter_en,
    input wire tx_fifo_flush, input wire rx_fifo_flush,
    output wire tx_empty, output wire tx_full,
    output wire [FAW-1:0] tx_level,
    output wire tx_level_below,
    output wire [MDW-1:0] rdata,
    output wire rx_empty, output wire rx_full,
    output wire [FAW-1:0] rx_level,
    output wire rx_level_above,
    output wire break_flag, output wire match_flag,
    output wire frame_error_flag, output wire parity_error_flag,
    output wire overrun_flag, output wire timeout_flag,
    input wire rx, output wire tx
);
    wire baudtick;
    wire rx_sync, rx_filtered, rx_input;
    wire [MDW-1:0] tx_data, rx_data;
    wire tx_done, rx_done;

    ef_util_sync rxsync (.clk(clk), .in(rx), .out(rx_sync));

    ef_util_glitch_filter #(.N(GFLEN)) filter (
        .clk(clk), .rst_n(rst_n), .in(rx_sync),
        .en(glitch_filter_en), .out(rx_filtered)
    );

    assign rx_input = loopback_en ? tx :
                      glitch_filter_en ? rx_filtered : rx_sync;

    BAUDGEN baud (
        .clk(clk), .rst_n(rst_n), .prescale(prescaler),
        .en(en), .baudtick(baudtick)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) txfifo (
        .clk(clk), .rst_n(rst_n), .rd(tx_done), .wr(wr),
        .flush(tx_fifo_flush), .wdata(wdata),
        .empty(tx_empty), .full(tx_full),
        .rdata(tx_data), .level(tx_level)
    );

    ef_util_fifo #(.DW(MDW), .AW(FAW)) rxfifo (
        .clk(clk), .rst_n(rst_n), .rd(rd), .wr(rx_done),
        .flush(rx_fifo_flush), .wdata(rx_data),
        .empty(rx_empty), .full(rx_full),
        .rdata(rdata), .level(rx_level)
    );

    UART_TX #(.NUM_SAMPLES(SC), .MDW(MDW)) transmitter (
        .clk(clk), .resetn(rst_n), .tx_start(!tx_empty),
        .b_tick(baudtick && tx_en), .data_size(data_size),
        .stop_bits_count(stop_bits_count), .parity_type(parity_type),
        .d_in(tx_data), .tx_done(tx_done), .tx(tx)
    );

    UART_RX #(.NUM_SAMPLES(SC), .MDW(MDW)) receiver (
        .clk(clk), .resetn(rst_n), .b_tick(baudtick && rx_en),
        .data_size(data_size), .stop_bits_count(stop_bits_count),
        .parity_type(parity_type), .rx(rx_input),
        .match_data(match_data), .rx_done(rx_done),
        .parity_error(parity_error_flag),
        .frame_error(frame_error_flag),
        .break_flag(break_flag), .match_flag(match_flag),
        .dout(rx_data)
    );

    reg [5:0] timeout_count;
    reg [15:0] timeout_samples;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            timeout_count <= 0;
            timeout_samples <= 0;
        end else if (rx_done) begin
            timeout_count <= 0;
            timeout_samples <= 0;
        end else if (baudtick && rx_en) begin
            if (timeout_samples == SC-1) begin
                timeout_samples <= 0;
                if (timeout_count == timeout_bits)
                    timeout_count <= 0;
                else
                    timeout_count <= timeout_count + 1'b1;
            end else
                timeout_samples <= timeout_samples + 1'b1;
        end
    end

    assign tx_level_below = (tx_level < txfifotr) && !tx_full;
    assign rx_level_above = (rx_level > rxfifotr) || rx_full;
    assign overrun_flag = rx_done && rx_full;
    assign timeout_flag = (timeout_count == timeout_bits);
endmodule

module EF_UART_APB #(
    parameter SC=8, MDW=9, GFLEN=8, FAW=4
) (
    input wire PCLK,
    input wire PRESETn,
    input wire PWRITE,
    input wire [31:0] PWDATA,
    input wire [31:0] PADDR,
    input wire PENABLE,
    input wire PSEL,
    output wire PREADY,
    output wire [31:0] PRDATA,
    output wire IRQ,
    input wire [1-1:0] rx,
    output wire [1-1:0] tx
);
    localparam RXDATA=16'h0000, TXDATA=16'h0004,
               PR=16'h0008, CTRL=16'h000c, CFG=16'h0010,
               MATCH=16'h001c,
               RX_LEVEL=16'hfe00, RX_THRESHOLD=16'hfe04,
               RX_FLUSH=16'hfe08, TX_LEVEL=16'hfe10,
               TX_THRESHOLD=16'hfe14, TX_FLUSH=16'hfe18,
               IM=16'hff00, MIS=16'hff04, RIS=16'hff08,
               IC=16'hff0c, GCLK=16'hff10;

    wire apb_valid = PSEL && PENABLE;
    wire apb_wr = apb_valid && PWRITE;
    wire apb_rd = apb_valid && !PWRITE;
    wire [15:0] addr = PADDR[15:0];

    reg [15:0] pr_reg;
    reg [4:0] ctrl_reg;
    reg [13:0] cfg_reg;
    reg [MDW-1:0] match_reg;
    reg [FAW-1:0] rx_threshold_reg, tx_threshold_reg;
    reg rx_flush_reg, tx_flush_reg;
    reg [9:0] im_reg, ic_reg, ris_reg;
    reg gclk_reg;

    wire [MDW-1:0] rdata;
    wire [FAW-1:0] rx_level, tx_level;
    wire rx_empty, rx_full, tx_empty, tx_full;
    wire tx_level_below, rx_level_above;
    wire break_flag, match_flag, frame_error_flag;
    wire parity_error_flag, overrun_flag, timeout_flag;

    wire fifo_rd = apb_rd && (addr == RXDATA);
    wire fifo_wr = apb_wr && (addr == TXDATA);

    wire [9:0] raw_status = {
        timeout_flag, overrun_flag, parity_error_flag, frame_error_flag,
        match_flag, break_flag, rx_level_above, tx_level_below,
        rx_full, tx_empty
    };

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            pr_reg <= 0;
            ctrl_reg <= 0;
            cfg_reg <= 14'h3f08;
            match_reg <= 0;
            rx_threshold_reg <= 0;
            tx_threshold_reg <= 0;
            rx_flush_reg <= 0;
            tx_flush_reg <= 0;
            im_reg <= 0;
            ic_reg <= 0;
            gclk_reg <= 0;
        end else begin
            rx_flush_reg <= 1'b0;
            tx_flush_reg <= 1'b0;
            ic_reg <= 10'b0;

            if (apb_wr && addr == PR)
                pr_reg <= PWDATA[15:0];
            if (apb_wr && addr == CTRL)
                ctrl_reg <= PWDATA[4:0];
            if (apb_wr && addr == CFG)
                cfg_reg <= PWDATA[13:0];
            if (apb_wr && addr == MATCH)
                match_reg <= PWDATA[MDW-1:0];
            if (apb_wr && addr == RX_THRESHOLD)
                rx_threshold_reg <= PWDATA[FAW-1:0];
            if (apb_wr && addr == TX_THRESHOLD)
                tx_threshold_reg <= PWDATA[FAW-1:0];
            if (apb_wr && addr == RX_FLUSH)
                rx_flush_reg <= PWDATA[0];
            if (apb_wr && addr == TX_FLUSH)
                tx_flush_reg <= PWDATA[0];
            if (apb_wr && addr == IM)
                im_reg <= PWDATA[9:0];
            if (apb_wr && addr == IC)
                ic_reg <= PWDATA[9:0];
            if (apb_wr && addr == GCLK)
                gclk_reg <= PWDATA[0];
        end
    end

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            ris_reg <= 10'b0;
        else
            ris_reg <= (ris_reg & ~ic_reg) | raw_status;
    end

    EF_UART #(.SC(SC), .MDW(MDW), .GFLEN(GFLEN), .FAW(FAW)) uart (
        .clk(PCLK), .rst_n(PRESETn),
        .prescaler(pr_reg),
        .en(ctrl_reg[0]), .tx_en(ctrl_reg[1]), .rx_en(ctrl_reg[2]),
        .loopback_en(ctrl_reg[3]), .glitch_filter_en(ctrl_reg[4]),
        .rd(fifo_rd), .wr(fifo_wr), .wdata(PWDATA[MDW-1:0]),
        .data_size(cfg_reg[3:0]),
        .stop_bits_count(cfg_reg[4]),
        .parity_type(cfg_reg[7:5]),
        .timeout_bits(cfg_reg[13:8]),
        .txfifotr(tx_threshold_reg), .rxfifotr(rx_threshold_reg),
        .match_data(match_reg),
        .tx_fifo_flush(tx_flush_reg),
        .rx_fifo_flush(rx_flush_reg),
        .tx_empty(tx_empty), .tx_full(tx_full), .tx_level(tx_level),
        .tx_level_below(tx_level_below),
        .rdata(rdata),
        .rx_empty(rx_empty), .rx_full(rx_full), .rx_level(rx_level),
        .rx_level_above(rx_level_above),
        .break_flag(break_flag), .match_flag(match_flag),
        .frame_error_flag(frame_error_flag),
        .parity_error_flag(parity_error_flag),
        .overrun_flag(overrun_flag), .timeout_flag(timeout_flag),
        .rx(rx), .tx(tx)
    );

    assign PRDATA =
        (addr == RXDATA)      ? {{(32-MDW){1'b0}},rdata} :
        (addr == PR)         ? {{16{1'b0}},pr_reg} :
        (addr == CTRL)       ? {{27{1'b0}},ctrl_reg} :
        (addr == CFG)        ? {{18{1'b0}},cfg_reg} :
        (addr == MATCH)      ? {{(32-MDW){1'b0}},match_reg} :
        (addr == RX_LEVEL)   ? {{(32-FAW){1'b0}},rx_level} :
        (addr == RX_THRESHOLD) ? {{(32-FAW){1'b0}},rx_threshold_reg} :
        (addr == RX_FLUSH)   ? {{31{1'b0}},rx_flush_reg} :
        (addr == TX_LEVEL)   ? {{(32-FAW){1'b0}},tx_level} :
        (addr == TX_THRESHOLD) ? {{(32-FAW){1'b0}},tx_threshold_reg} :
        (addr == TX_FLUSH)   ? {{31{1'b0}},tx_flush_reg} :
        (addr == IM)         ? {{22{1'b0}},im_reg} :
        (addr == MIS)        ? {{22{1'b0}},(ris_reg & im_reg)} :
        (addr == RIS)        ? {{22{1'b0}},ris_reg} :
        (addr == GCLK)       ? {{31{1'b0}},gclk_reg} :
        32'hdeadbeef;

    assign IRQ = |(ris_reg & im_reg);
    assign PREADY = 1'b1;
endmodule

