module ef_util_ticker #(parameter W=8) (
    input wire clk, input wire rst_n, input wire en,
    input wire [W-1:0] clk_div, output wire tick
);
    reg [W-1:0] counter;
    reg tick_reg;
    wire zero = (counter == {W{1'b0}});
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= {W{1'b0}};
            tick_reg <= 1'b0;
        end else if (en) begin
            counter <= zero ? clk_div : counter - 1'b1;
            tick_reg <= (clk_div == {W{1'b0}}) ? 1'b1 : zero;
        end else begin
            tick_reg <= 1'b0;
        end
    end
    assign tick = tick_reg;
endmodule

module ef_util_glitch_filter #(parameter N=8, CLKDIV=8'd1) (
    input wire clk, input wire rst_n, input wire in, input wire en,
    output reg out
);
    reg [N-1:0] shifter;
    wire tick;
    ef_util_ticker #(.W(8)) ticker (
        .clk(clk), .rst_n(rst_n), .en(en), .clk_div(CLKDIV), .tick(tick)
    );
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shifter <= {N{1'b0}};
            out <= 1'b0;
        end else if (tick) begin
            shifter <= {shifter[N-2:0], in};
            if (&{shifter[N-2:0], in})
                out <= 1'b1;
            else if (~|{shifter[N-2:0], in})
                out <= 1'b0;
        end
    end
endmodule

module ef_util_fifo #(parameter DW=8, AW=4) (
    input wire clk, input wire rst_n,
    input wire rd, input wire wr, input wire flush,
    input wire [DW-1:0] wdata,
    output wire empty, output wire full,
    output wire [DW-1:0] rdata,
    output wire [AW-1:0] level
);
    localparam DEPTH = 2**AW;
    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] wptr, rptr, level_reg;
    reg full_reg, empty_reg;
    wire write_accept = wr && !full_reg;
    wire read_accept = rd && !empty_reg;

    always @(posedge clk) begin
        if (write_accept)
            mem[wptr] <= wdata;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wptr <= {AW{1'b0}};
            rptr <= {AW{1'b0}};
            level_reg <= {AW{1'b0}};
            full_reg <= 1'b0;
            empty_reg <= 1'b1;
        end else if (flush) begin
            wptr <= {AW{1'b0}};
            rptr <= {AW{1'b0}};
            level_reg <= {AW{1'b0}};
            full_reg <= 1'b0;
            empty_reg <= 1'b1;
        end else begin
            case ({write_accept,read_accept})
                2'b10: begin
                    wptr <= wptr + 1'b1;
                    level_reg <= level_reg + 1'b1;
                    empty_reg <= 1'b0;
                    if ((wptr + 1'b1) == rptr)
                        full_reg <= 1'b1;
                end
                2'b01: begin
                    rptr <= rptr + 1'b1;
                    level_reg <= level_reg - 1'b1;
                    full_reg <= 1'b0;
                    if ((rptr + 1'b1) == wptr)
                        empty_reg <= 1'b1;
                end
                2'b11: begin
                    wptr <= wptr + 1'b1;
                    rptr <= rptr + 1'b1;
                end
                default: ;
            endcase
        end
    end

    assign rdata = mem[rptr];
    assign empty = empty_reg;
    assign full = full_reg;
    assign level = level_reg;
endmodule

