module ef_util_sync #(parameter NUM_STAGES = 2) (
    input wire clk, input wire in, output wire out
);
    reg [NUM_STAGES-1:0] sync;
    always @(posedge clk)
        sync <= {sync[NUM_STAGES-2:0], in};
    assign out = sync[NUM_STAGES-1];
endmodule

module ef_util_ticker #(parameter W=8) (
    input wire clk, input wire rst_n, input wire en,
    input wire [W-1:0] clk_div, output wire tick
);
    reg [W-1:0] counter;
    reg tick_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= '0;
            tick_reg <= 1'b0;
        end else if (en) begin
            tick_reg <= (clk_div == '0) ? 1'b1 : (counter == '0);
            if (counter == '0)
                counter <= clk_div;
            else
                counter <= counter - 1'b1;
        end else begin
            tick_reg <= 1'b0;
        end
    end

    assign tick = tick_reg;
endmodule

module ef_util_glitch_filter #(parameter N=8, CLKDIV=8'd1) (
    input wire clk, input wire rst_n, input wire in, input wire en,
    output reg out
);
    reg [N-1:0] shifter;
    wire tick;

    ef_util_ticker #(.W(8)) ticker (
        .clk(clk), .rst_n(rst_n), .en(en),
        .clk_div(CLKDIV), .tick(tick)
    );

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shifter <= '0;
            out <= 1'b0;
        end else if (tick) begin
            shifter <= {shifter[N-2:0], in};
            if (&shifter)
                out <= 1'b1;
            else if (~|shifter)
                out <= 1'b0;
        end
    end
endmodule

module ef_util_fifo #(parameter DW=8, AW=4) (
    input wire clk, input wire rst_n,
    input wire rd, input wire wr, input wire flush,
    input wire [DW-1:0] wdata,
    output wire empty, output wire full,
    output wire [DW-1:0] rdata,
    output wire [AW-1:0] level
);
    localparam DEPTH = 1 << AW;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] wptr, rptr;
    reg [AW-1:0] level_reg;
    reg empty_reg, full_reg;
    wire do_write = wr && !full_reg;
    wire do_read = rd && (!empty_reg || do_write);

    always @(posedge clk) begin
        if (do_write)
            mem[wptr] <= wdata;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wptr <= '0;
            rptr <= '0;
            level_reg <= '0;
            empty_reg <= 1'b1;
            full_reg <= 1'b0;
        end else if (flush) begin
            wptr <= '0;
            rptr <= '0;
            level_reg <= '0;
            empty_reg <= 1'b1;
            full_reg <= 1'b0;
        end else begin
            if (do_write)
                wptr <= wptr + 1'b1;
            if (do_read)
                rptr <= rptr + 1'b1;

            case ({do_write,do_read})
                2'b10: begin
                    level_reg <= level_reg + 1'b1;
                    empty_reg <= 1'b0;
                    if ((wptr + 1'b1) == rptr)
                        full_reg <= 1'b1;
                end
                2'b01: begin
                    level_reg <= level_reg - 1'b1;
                    full_reg <= 1'b0;
                    if ((rptr + 1'b1) == wptr)
                        empty_reg <= 1'b1;
                end
                default: begin
                    level_reg <= level_reg;
                    empty_reg <= empty_reg;
                    full_reg <= full_reg;
                end
            endcase
        end
    end

    assign rdata = mem[rptr];
    assign empty = empty_reg;
    assign full = full_reg;
    assign level = level_reg;
endmodule

