module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn, input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error, output wire frame_error,
    output wire break_flag, output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
               PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;

    reg [2:0] state, next_state;
    reg [15:0] sample_count, next_sample_count;
    reg [3:0] bit_count, next_bit_count;
    reg [MDW-1:0] data_reg, next_data;
    reg parity_err_reg, next_parity_err;
    reg frame_err_reg, next_frame_err;
    reg [11:0] break_shift;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= '0;
            bit_count <= '0;
            data_reg <= '0;
            parity_err_reg <= 1'b0;
            frame_err_reg <= 1'b0;
        end else begin
            state <= next_state;
            sample_count <= next_sample_count;
            bit_count <= next_bit_count;
            data_reg <= next_data;
            parity_err_reg <= next_parity_err;
            frame_err_reg <= next_frame_err;
        end
    end

    always @* begin
        next_state = state;
        next_sample_count = sample_count;
        next_bit_count = bit_count;
        next_data = data_reg;
        next_parity_err = parity_err_reg;
        next_frame_err = frame_err_reg;
        rx_done = 1'b0;

        if (state == IDLE) begin
            next_parity_err = 1'b0;
            next_frame_err = 1'b0;
        end

        case (state)
            IDLE: begin
                if (b_tick && !rx) begin
                    next_state = START;
                    next_sample_count = 0;
                end
            end

            START: begin
                if (b_tick) begin
                    if (sample_count == (NUM_SAMPLES/2)-1) begin
                        next_state = DATA;
                        next_sample_count = 0;
                        next_bit_count = 0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            DATA: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_data = {rx, data_reg[MDW-1:1]};
                        if (bit_count == data_size-1) begin
                            next_state = (parity_type == 3'b000) ?
                                         STOP0 : PARITY;
                        end else begin
                            next_bit_count = bit_count + 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            PARITY: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = STOP0;
                        case (parity_type)
                            3'b001: if ((~^dout) != rx) next_parity_err = 1'b1;
                            3'b010: if ((^dout)  != rx) next_parity_err = 1'b1;
                            3'b100: if (rx != 1'b0) next_parity_err = 1'b1;
                            3'b101: if (rx != 1'b1) next_parity_err = 1'b1;
                            default: ;
                        endcase
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            STOP0: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        if (!rx) next_frame_err = 1'b1;
                        if (stop_bits_count)
                            next_state = STOP1;
                        else begin
                            next_state = IDLE;
                            rx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            STOP1: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_state = IDLE;
                        rx_done = 1'b1;
                        if (!rx) next_frame_err = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = IDLE;
        endcase
