    always @(posedge clk or negedge resetn) begin
        if (!resetn)
            break_shift <= 12'hfff;
        else if (b_tick && (sample_count == NUM_SAMPLES-1)) begin
            if (state == IDLE)
                break_shift <= 12'hfff;
            else
                break_shift <= {break_shift[10:0], rx};
        end
    end

    assign dout = data_reg >> (MDW-data_size);
    assign parity_error = parity_err_reg && rx_done;
    assign frame_error = frame_err_reg && rx_done;
    assign break_flag = (break_shift == 12'd0);
    assign match_flag = (dout == match_data) && rx_done;
