module UART_RX #(parameter NUM_SAMPLES=16, MDW=8) (
    input wire clk, input wire resetn, input wire b_tick,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire rx,
    input wire [MDW-1:0] match_data,
    output reg rx_done,
    output wire parity_error,
    output wire frame_error,
    output wire break_flag,
    output wire match_flag,
    output wire [MDW-1:0] dout
);
    localparam IDLE=3'd0, START=3'd1, DATA=3'd2,
                 PARITY=3'd3, STOP0=3'd4, STOP1=3'd5;
    reg [2:0] state;
    reg [4:0] sample_count;
    reg [3:0] bit_count;
    reg [MDW-1:0] data;
    reg parity_err_r, frame_err_r;
    reg [11:0] break_count;

    wire parity_expected =
        (parity_type == 3'b001) ? ~(^data) :
        (parity_type == 3'b010) ?  (^data) :
        (parity_type == 3'b100) ? 1'b0 :
        (parity_type == 3'b101) ? 1'b1 : 1'b0;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= IDLE;
            sample_count <= 0;
            bit_count <= 0;
            data <= 0;
            parity_err_r <= 0;
            frame_err_r <= 0;
            rx_done <= 0;
            break_count <= 12'hfff;
        end else begin
            rx_done <= 1'b0;
            if (b_tick && (sample_count == NUM_SAMPLES-1)) begin
                if (state != IDLE)
                    break_count <= {break_count[10:0],rx};
                else
                    break_count <= 12'hfff;
            end

            case (state)
                IDLE: begin
                    sample_count <= 0;
                    if (b_tick && !rx) begin
                        state <= START;
                        sample_count <= 0;
                        parity_err_r <= 0;
                        frame_err_r <= 0;
                    end
                end
                START: begin
                    if (b_tick) begin
                        if (sample_count == (NUM_SAMPLES/2)-1) begin
                            sample_count <= 0;
                            bit_count <= 0;
                            state <= DATA;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end
                DATA: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            data <= {rx,data[MDW-1:1]};
                            if (bit_count == data_size-1)
                                state <= (parity_type == 0) ? STOP0 : PARITY;
                            else
                                bit_count <= bit_count + 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end
                PARITY: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            parity_err_r <= (rx != parity_expected);
                            state <= STOP0;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end
                STOP0: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            frame_err_r <= !rx;
                            if (stop_bits_count)
                                state <= STOP1;
                            else begin
                                state <= IDLE;
                                rx_done <= 1'b1;
                            end
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end
                STOP1: begin
                    if (b_tick) begin
                        if (sample_count == NUM_SAMPLES-1) begin
                            sample_count <= 0;
                            frame_err_r <= frame_err_r | !rx;
                            state <= IDLE;
                            rx_done <= 1'b1;
                        end else
                            sample_count <= sample_count + 1'b1;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    assign dout = data;
    assign parity_error = parity_err_r & rx_done;
    assign frame_error = frame_err_r & rx_done;
    assign match_flag = (data == match_data) & rx_done;
    assign break_flag = (break_count == 0);
endmodule

