                if (state == IDLE)
                    break_shift <= 12'hfff;
                else
                    break_shift <= {break_shift[10:0],rx};
            end
        end
    end

    always @* begin
        next_state = state;
        next_sample_count = sample_count;
        next_bit_count = bit_count;
        next_data_reg = data_reg;
        next_parity_error = parity_error_reg;
        next_frame_error = frame_error_reg;
        rx_done = 1'b0;

        if (state == IDLE) begin
            next_parity_error = 1'b0;
            next_frame_error = 1'b0;
        end

        case (state)
            IDLE: begin
                if (!rx && b_tick) begin
                    next_state = START;
                    next_sample_count = 0;
                end
            end

            START: begin
                if (b_tick) begin
                    if (sample_count == (NUM_SAMPLES/2)-1) begin
                        next_state = DATA;
                        next_sample_count = 0;
                        next_bit_count = 0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            DATA: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        next_data_reg = {rx,data_reg[MDW-1:1]};
                        if (bit_count == data_size-1) begin
                            if (parity_type == 3'b000)
                                next_state = STOP0;
                            else
                                next_state = PARITY;
                        end else
                            next_bit_count = bit_count + 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            PARITY: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        case (parity_type)
                            3'b001:
                                if ((~^dout) != rx) next_parity_error = 1'b1;
                            3'b010:
                                if ((^dout) != rx) next_parity_error = 1'b1;
                            3'b100:
                                if (rx != 1'b0) next_parity_error = 1'b1;
                            3'b101:
                                if (rx != 1'b1) next_parity_error = 1'b1;
                            default: begin
                            end
                        endcase
                        next_state = STOP0;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            STOP0: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        if (!rx) next_frame_error = 1'b1;
                        if (stop_bits_count)
                            next_state = STOP1;
                        else begin
                            next_state = IDLE;
                            rx_done = 1'b1;
                        end
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            STOP1: begin
                if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        next_sample_count = 0;
                        if (!rx) next_frame_error = 1'b1;
                        next_state = IDLE;
                        rx_done = 1'b1;
                    end else
                        next_sample_count = sample_count + 1'b1;
                end
            end

            default: next_state = IDLE;
        endcase
    end

    assign dout = data_reg >> (MDW-data_size);
    assign parity_error = parity_error_reg & rx_done;
    assign frame_error = frame_error_reg & rx_done;
    assign match_flag = (dout == match_data) & rx_done;
    assign break_flag = (break_shift == 12'd0);
endmodule

