module ef_util_ticker #(parameter W=8) (
    input wire clk, input wire rst_n, input wire en,
    input wire [W-1:0] clk_div, output wire tick
);
    reg [W-1:0] count;
    always @(posedge clk or negedge rst_n)
        if (!rst_n) count <= 0;
        else if (en)
            count <= (count == 0) ? clk_div : count - 1'b1;
    assign tick = en && ((clk_div == 0) || (count == 0));
endmodule

module ef_util_glitch_filter #(parameter N=8, CLKDIV=8'd1) (
    input wire clk, input wire rst_n, input wire in, input wire en,
    output reg out
);
    reg [N-1:0] shifter;
    wire tick;
    ef_util_ticker #(.W(8)) ticker (
        .clk(clk), .rst_n(rst_n), .en(en), .clk_div(CLKDIV), .tick(tick)
    );
    always @(posedge clk or negedge rst_n)
        if (!rst_n) begin
            shifter <= 0;
            out <= 1'b0;
        end else if (tick) begin
            shifter <= {shifter[N-2:0],in};
            if (&shifter) out <= 1'b1;
            else if (!(|shifter)) out <= 1'b0;
        end
endmodule

module ef_util_fifo #(parameter DW=8, AW=4) (
    input wire clk, input wire rst_n,
    input wire rd, input wire wr, input wire flush,
    input wire [DW-1:0] wdata,
    output wire empty, output wire full,
    output wire [DW-1:0] rdata,
    output wire [AW-1:0] level
);
    localparam DEPTH = 1 << AW;
    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] rp, wp, lev;
    reg emp, ful;
    wire do_wr = wr && !ful;
    wire do_rd = rd && !emp;

    always @(posedge clk)
        if (do_wr) mem[wp] <= wdata;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rp <= 0; wp <= 0; lev <= 0; emp <= 1'b1; ful <= 1'b0;
        end else if (flush) begin
            rp <= 0; wp <= 0; lev <= 0; emp <= 1'b1; ful <= 1'b0;
        end else begin
            if (do_wr) wp <= wp + 1'b1;
            if (do_rd) rp <= rp + 1'b1;
            case ({do_wr,do_rd})
                2'b10: begin
                    lev <= lev + 1'b1;
                    emp <= 1'b0;
                    if ((wp + 1'b1) == rp) ful <= 1'b1;
                end
                2'b01: begin
                    lev <= lev - 1'b1;
                    ful <= 1'b0;
                    if ((rp + 1'b1) == wp) emp <= 1'b1;
                end
                2'b11: begin
                    wp <= wp + 1'b1;
                    rp <= rp + 1'b1;
                end
                default: ;
            endcase
        end
    end

    assign rdata = mem[rp];
    assign empty = emp;
    assign full  = ful;
    assign level = lev;
endmodule

