                        else bit_count <= bit_count + 1'b1;
                    end else sample_count <= sample_count + 1'b1;
                end
                PARITY: if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        sample_count <= 0;
                        case (parity_type)
                            3'b001: parity_bad <= (rx != ~^data);
                            3'b010: parity_bad <= (rx != ^data);
                            3'b100: parity_bad <= (rx != 1'b0);
                            3'b101: parity_bad <= (rx != 1'b1);
