                        if (stop_bits_count) state <= STOP1;
                        else begin
                            state <= IDLE;
                            completed_data <= data;
                            rx_done <= 1'b1;
                            parity_error <= parity_bad;
                            frame_error <= !rx;
                            match_flag <= (data == match_data);
                        end
                    end else sample_count <= sample_count + 1'b1;
                end
                STOP1: if (b_tick) begin
                    if (sample_count == NUM_SAMPLES-1) begin
                        state <= IDLE;
                        sample_count <= 0;
                        completed_data <= data;
                        rx_done <= 1'b1;
                        parity_error <= parity_bad;
                        frame_error <= frame_bad | !rx;
                        match_flag <= (data == match_data);
                    end else sample_count <= sample_count + 1'b1;
                end
                default: state <= IDLE;
            endcase
        end
    end

