    BAUDGEN baud_i (
        .clk(clk),.rst_n(rst_n),.prescale(prescaler),
        .en(en),.baudtick(b_tick)
    );

    ef_util_fifo #(.DW(MDW),.AW(FAW)) tx_fifo (
        .clk(clk),.rst_n(rst_n),.rd(tx_done),.wr(wr),
        .flush(tx_fifo_flush),.wdata(wdata),.empty(tx_empty),
        .full(tx_full),.rdata(tx_data),.level(tx_level)
    );

