        .clk(clk),.rst_n(rst_n),.rd(rd),.wr(rx_done),
        .flush(rx_fifo_flush),.wdata(rx_data),.empty(rx_empty),
        .full(rx_full),.rdata(rdata),.level(rx_level)
    );

