        if (!PRESETn) begin
            pr_reg <= 0;
            ctrl_reg <= 0;
            cfg_reg <= 14'h3f08;
            match_reg <= 0;
            rx_thresh_reg <= 0;
            tx_thresh_reg <= 0;
            rx_flush_reg <= 0;
            tx_flush_reg <= 0;
            gclk_reg <= 0;
            im_reg <= 0;
            ic_reg <= 0;
        end else begin
            rx_flush_reg <= 0;
            tx_flush_reg <= 0;
            ic_reg <= 0;
            if (we && addr == PR) pr_reg <= PWDATA[15:0];
            if (we && addr == CTRL) ctrl_reg <= PWDATA[4:0];
            if (we && addr == CFG) cfg_reg <= PWDATA[13:0];
            if (we && addr == MATCH) match_reg <= PWDATA[MDW-1:0];
            if (we && addr == RXTHRESH) rx_thresh_reg <= PWDATA[3:0];
            if (we && addr == TXTHRESH) tx_thresh_reg <= PWDATA[3:0];
            if (we && addr == RXFLUSH) rx_flush_reg <= PWDATA[0];
            if (we && addr == TXFLUSH) tx_flush_reg <= PWDATA[0];
            if (we && addr == GCLK) gclk_reg <= PWDATA[0];
