            if (ic_reg[6]) ris_reg[6] <= 0; else if (fe) ris_reg[6] <= 1;
            if (ic_reg[7]) ris_reg[7] <= 0; else if (pre) ris_reg[7] <= 1;
            if (ic_reg[8]) ris_reg[8] <= 0; else if (overrun) ris_reg[8] <= 1;
