    EF_UART #(.SC(SC),.MDW(MDW),.GFLEN(GFLEN),.FAW(FAW)) core (
        .clk(PCLK), .rst_n(PRESETn), .prescaler(pr_reg),
        .en(ctrl_reg[0]), .tx_en(ctrl_reg[1]), .rx_en(ctrl_reg[2]),
        .rd(re && addr == RXDATA), .wr(we && addr == TXDATA),
        .wdata(PWDATA[MDW-1:0]), .data_size(cfg_reg[3:0]),
        .stop_bits_count(cfg_reg[4]), .parity_type(cfg_reg[7:5]),
        .txfifotr(tx_thresh_reg), .rxfifotr(rx_thresh_reg),
        .match_data(match_reg), .timeout_bits(cfg_reg[13:8]),
        .loopback_en(ctrl_reg[3]), .glitch_filter_en(ctrl_reg[4]),
        .tx_fifo_flush(tx_flush_reg), .rx_fifo_flush(rx_flush_reg),
        .tx_empty(tx_empty), .tx_full(tx_full), .tx_level(tx_level),
        .tx_level_below(tx_below), .rdata(rdata),
        .rx_empty(rx_empty), .rx_full(rx_full), .rx_level(rx_level),
        .rx_level_above(rx_above), .break_flag(brk), .match_flag(match),
        .frame_error_flag(fe), .parity_error_flag(pre),
        .overrun_flag(overrun), .timeout_flag(rto), .rx(rx), .tx(tx)
    );

    always @* begin
        case (addr)
            RXDATA:   PRDATA = {{(32-MDW){1'b0}},rdata};
            PR:       PRDATA = {{16{1'b0}},pr_reg};
            CTRL:     PRDATA = {{27{1'b0}},ctrl_reg};
            CFG:      PRDATA = {{18{1'b0}},cfg_reg};
            MATCH:    PRDATA = {{(32-MDW){1'b0}},match_reg};
            RXLEVEL:  PRDATA = {{(32-FAW){1'b0}},rx_level};
