        if(!rst_n) counter<='b0;
        else if(en) counter<=zero?clk_div:counter-1'b1;
    always @(posedge clk or negedge rst_n)
        if(!rst_n) tick_reg<=1'b0;
        else if(en) tick_reg<=(clk_div=='b0)?1'b1:zero;
