    always @(posedge clk or negedge rst_n)
        if(!rst_n) shifter<='b0;
        else if(tick) shifter<={shifter[N-2:0],in};
    always @(posedge clk or negedge rst_n)
        if(!rst_n) out<=1'b0;
        else if(&shifter) out<=1'b1;
        else if(!( |shifter)) out<=1'b0;
