module ef_util_fifo #(parameter DW=8,AW=4)(
    input wire clk,input wire rst_n,input wire rd,input wire wr,input wire flush,
    input wire [DW-1:0] wdata,output wire empty,output wire full,
    output wire [DW-1:0] rdata,output wire [AW-1:0] level
);
    localparam DEPTH=2**AW;
    reg [DW-1:0] mem[0:DEPTH-1];
    reg [AW-1:0] wp,rp,lev;
    reg f,e;
    wire wacc=wr&~f;
    always @(posedge clk)
        if(wacc) mem[wp]<=wdata;
    assign rdata=mem[rp];
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin wp<=0;rp<=0;lev<=0;f<=0;e<=1; end
        else if(flush) begin wp<=0;rp<=0;lev<=0;f<=0;e<=1; end
        else begin
            case({wacc,rd})
                2'b10: begin
                    wp<=wp+1'b1; lev<=lev+1'b1; e<=0;
                    if(wp+1'b1==rp) f<=1;
                end
                2'b01: if(!e) begin
                    rp<=rp+1'b1; lev<=lev-1'b1; f<=0;
                    if(rp+1'b1==wp) e<=1;
                end
                2'b11: begin
                    wp<=wp+1'b1; rp<=rp+1'b1;
                end
                default: ;
            endcase
        end
    end
    assign empty=e;
    assign full=f;
    assign level=lev;
endmodule

