                else ndc=dc+1'b1;
            end else nbc=bc+1'b1;
        end
        PARITY: begin
            case(parity_type)
                3'b001: ntxr=~^pdata;
                3'b010: ntxr=^pdata;
                3'b100: ntxr=0;
                3'b101: ntxr=1;
                default: ntxr=0;
            endcase
            if(b_tick) if(bc==NUM_SAMPLES-1) begin nstate=STOP0;nbc=0;end
            else nbc=bc+1'b1;
        end
        STOP0: begin
            ntxr=1;
            if(b_tick) if(bc==NUM_SAMPLES-1) begin
                nbc=0;
                if(stop_bits_count) nstate=STOP1;
                else begin nstate=IDLE;tx_done=1;end
            end else nbc=bc+1'b1;
        end
        STOP1: begin
            ntxr=1;
            if(b_tick) if(bc==NUM_SAMPLES-1) begin
                nstate=IDLE;nbc=0;tx_done=1;
