    input wire rst_n,
    input wire [15:0] prescaler,
    input wire en,
    input wire tx_en,
    input wire rx_en,
    input wire rd,
    input wire wr,
    input wire [MDW-1:0] wdata,
    input wire [3:0] data_size,
    input wire stop_bits_count,
    input wire [2:0] parity_type,
    input wire [3:0] txfifotr,
    input wire [3:0] rxfifotr,
    input wire [MDW-1:0] match_data,
    input wire [5:0] timeout_bits,
    input wire loopback_en,
    input wire glitch_filter_en,
    input wire tx_fifo_flush,
    input wire rx_fifo_flush,
    output wire tx_empty,
    output wire tx_full,
    output wire [FAW-1:0] tx_level,
    output wire tx_level_below,
    output wire [MDW-1:0] rdata,
    output wire rx_empty,
    output wire rx_full,
    output wire [FAW-1:0] rx_level,
    output wire rx_level_above,
    output wire break_flag,
    output wire match_flag,
    output wire frame_error_flag,
    output wire parity_error_flag,
    output wire overrun_flag,
    output wire timeout_flag,
    input wire rx,
    output wire tx
);
    wire baud_tick;
    wire tx_done, rx_done;
    wire [MDW-1:0] tx_data, rx_data;
    wire rx_sync, rx_filtered, rx_input;

    ef_util_sync rx_sync_inst (
        .clk(clk), .in(rx), .out(rx_sync)
    );

    ef_util_glitch_filter #(.N(GFLEN)) glitch_filter (
        .clk(clk),
        .rst_n(rst_n),
        .in(rx_sync),
        .en(glitch_filter_en),
        .out(rx_filtered)
    );

    assign rx_input = loopback_en ? tx :
                      glitch_filter_en ? rx_filtered : rx_sync;

    BAUDGEN baudgen (
        .clk(clk),
        .rst_n(rst_n),
        .prescale(prescaler),
        .en(en),
        .baudtick(baud_tick)
    );

    ef_util_fifo #(.DW(MDW),.AW(FAW)) tx_fifo (
        .clk(clk),
        .rst_n(rst_n),
        .rd(tx_done),
        .wr(wr),
        .flush(tx_fifo_flush),
        .wdata(wdata),
        .empty(tx_empty),
        .full(tx_full),
        .rdata(tx_data),
        .level(tx_level)
    );

    UART_TX #(.NUM_SAMPLES(SC),.MDW(MDW)) transmitter (
        .clk(clk),
        .resetn(rst_n),
        .tx_start(!tx_empty),
        .b_tick(baud_tick && tx_en),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .d_in(tx_data),
        .tx_done(tx_done),
        .tx(tx)
    );

    ef_util_fifo #(.DW(MDW),.AW(FAW)) rx_fifo (
        .clk(clk),
        .rst_n(rst_n),
        .rd(rd),
        .wr(rx_done),
        .flush(rx_fifo_flush),
        .wdata(rx_data),
        .empty(rx_empty),
        .full(rx_full),
        .rdata(rdata),
        .level(rx_level)
    );

    UART_RX #(.NUM_SAMPLES(SC),.MDW(MDW)) receiver (
        .clk(clk),
        .resetn(rst_n),
        .b_tick(baud_tick && rx_en),
        .data_size(data_size),
        .stop_bits_count(stop_bits_count),
        .parity_type(parity_type),
        .rx(rx_input),
        .match_data(match_data),
        .rx_done(rx_done),
        .parity_error(parity_error_flag),
        .frame_error(frame_error_flag),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .dout(rx_data)
    );

    reg [5:0] timeout_count;
    reg [4:0] sample_count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            timeout_count <= 0;
            sample_count <= 0;
        end else if (baud_tick && rx_en) begin
            if (rx_done) begin
                timeout_count <= 0;
                sample_count <= 0;
            end else if (sample_count == SC-1) begin
                sample_count <= 0;
                if (timeout_flag)
                    timeout_count <= 0;
                else
                    timeout_count <= timeout_count + 1'b1;
            end else
                sample_count <= sample_count + 1'b1;
        end
    end

    assign tx_level_below = (tx_level < txfifotr) && !tx_full;
    assign rx_level_above = (rx_level > rxfifotr) || rx_full;
    assign overrun_flag = rx_full && rx_done;
    assign timeout_flag = (timeout_count == timeout_bits);
endmodule

module EF_UART_APB #(
    parameter SC=8,
    parameter MDW=9,
    parameter GFLEN=8,
    parameter FAW=4
) (
    input wire PCLK,
    input wire PRESETn,
    input wire PWRITE,
    input wire [31:0] PWDATA,
    input wire [31:0] PADDR,
    input wire PENABLE,
    input wire PSEL,
    output wire PREADY,
    output wire [31:0] PRDATA,
    output wire IRQ,
    input wire [1-1:0] rx,
    output wire [1-1:0] tx
);
    localparam RXDATA_OFF=16'h0000;
    localparam TXDATA_OFF=16'h0004;
    localparam PR_OFF=16'h0008;
    localparam CTRL_OFF=16'h000c;
    localparam CFG_OFF=16'h0010;
    localparam MATCH_OFF=16'h001c;
    localparam RX_LEVEL_OFF=16'hfe00;
    localparam RX_THRESH_OFF=16'hfe04;
    localparam RX_FLUSH_OFF=16'hfe08;
    localparam TX_LEVEL_OFF=16'hfe10;
    localparam TX_THRESH_OFF=16'hfe14;
    localparam TX_FLUSH_OFF=16'hfe18;
    localparam IM_OFF=16'hff00;
    localparam MIS_OFF=16'hff04;
    localparam RIS_OFF=16'hff08;
    localparam IC_OFF=16'hff0c;
    localparam GCLK_OFF=16'hff10;

    wire apb_valid = PSEL && PENABLE;
    wire apb_we = apb_valid && PWRITE;
    wire apb_re = apb_valid && !PWRITE;
    wire clk;

    reg gclk_reg;
    reg [15:0] pr_reg;
    reg [4:0] ctrl_reg;
    reg [13:0] cfg_reg;
    reg [MDW-1:0] match_reg;
    reg [FAW-1:0] rx_thresh_reg, tx_thresh_reg;
    reg rx_flush_reg, tx_flush_reg;
    reg [9:0] im_reg, ic_reg, ris_reg;

    ef_util_gating_cell gate (
        .clk(PCLK),
        .rst_n(PRESETn),
        .clk_en(gclk_reg),
        .clk_o(clk)
    );

    wire [FAW-1:0] tx_level, rx_level;
    wire tx_empty, tx_full, rx_empty, rx_full;
    wire tx_level_below, rx_level_above;
    wire [MDW-1:0] rx_data;
    wire break_flag, match_flag, frame_error_flag;
    wire parity_error_flag, overrun_flag, timeout_flag;
    wire rx_rd = apb_re && (PADDR[15:0] == RXDATA_OFF);
    wire tx_wr = apb_we && (PADDR[15:0] == TXDATA_OFF);

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn) begin
            gclk_reg <= 1'b0;
            pr_reg <= 16'd0;
            ctrl_reg <= 5'd0;
            cfg_reg <= 14'h3f08;
            match_reg <= 'b0;
            rx_thresh_reg <= 'b0;
            tx_thresh_reg <= 'b0;
            rx_flush_reg <= 1'b0;
            tx_flush_reg <= 1'b0;
            im_reg <= 'b0;
            ic_reg <= 'b0;
        end else begin
            rx_flush_reg <= 1'b0;
            tx_flush_reg <= 1'b0;
            ic_reg <= 10'd0;

            if (apb_we && PADDR[15:0] == GCLK_OFF)
                gclk_reg <= PWDATA[0];
            if (apb_we && PADDR[15:0] == PR_OFF)
                pr_reg <= PWDATA[15:0];
            if (apb_we && PADDR[15:0] == CTRL_OFF)
                ctrl_reg <= PWDATA[4:0];
            if (apb_we && PADDR[15:0] == CFG_OFF)
                cfg_reg <= PWDATA[13:0];
            if (apb_we && PADDR[15:0] == MATCH_OFF)
                match_reg <= PWDATA[MDW-1:0];
            if (apb_we && PADDR[15:0] == RX_THRESH_OFF)
                rx_thresh_reg <= PWDATA[FAW-1:0];
            if (apb_we && PADDR[15:0] == TX_THRESH_OFF)
                tx_thresh_reg <= PWDATA[FAW-1:0];
            if (apb_we && PADDR[15:0] == RX_FLUSH_OFF)
                rx_flush_reg <= PWDATA[0];
            if (apb_we && PADDR[15:0] == TX_FLUSH_OFF)
                tx_flush_reg <= PWDATA[0];
            if (apb_we && PADDR[15:0] == IM_OFF)
                im_reg <= PWDATA[9:0];
            if (apb_we && PADDR[15:0] == IC_OFF)
                ic_reg <= PWDATA[9:0];
        end
    end

    wire [9:0] raw_status = {
        timeout_flag,
        overrun_flag,
        parity_error_flag,
        frame_error_flag,
        match_flag,
        break_flag,
        rx_level_above,
        tx_level_below,
        rx_full,
        tx_empty
    };

    integer i;
    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            ris_reg <= 10'd0;
        else begin
            for (i=0; i<10; i=i+1) begin
                if (ic_reg[i])
                    ris_reg[i] <= 1'b0;
                else if (raw_status[i])
                    ris_reg[i] <= 1'b1;
            end
        end
    end

    EF_UART #(
        .SC(SC),
        .MDW(MDW),
        .GFLEN(GFLEN),
        .FAW(FAW)
    ) uart (
        .clk(clk),
        .rst_n(PRESETn),
        .prescaler(pr_reg),
        .en(ctrl_reg[0]),
        .tx_en(ctrl_reg[1]),
        .rx_en(ctrl_reg[2]),
        .loopback_en(ctrl_reg[3]),
        .glitch_filter_en(ctrl_reg[4]),
        .wdata(PWDATA[MDW-1:0]),
        .rd(rx_rd),
        .wr(tx_wr),
        .data_size(cfg_reg[3:0]),
        .stop_bits_count(cfg_reg[4]),
        .parity_type(cfg_reg[7:5]),
        .timeout_bits(cfg_reg[13:8]),
        .txfifotr(tx_thresh_reg),
        .rxfifotr(rx_thresh_reg),
        .match_data(match_reg),
        .tx_fifo_flush(tx_flush_reg),
        .rx_fifo_flush(rx_flush_reg),
        .tx_empty(tx_empty),
        .tx_full(tx_full),
        .tx_level(tx_level),
        .tx_level_below(tx_level_below),
        .rdata(rx_data),
        .rx_empty(rx_empty),
        .rx_full(rx_full),
        .rx_level(rx_level),
        .rx_level_above(rx_level_above),
        .break_flag(break_flag),
        .match_flag(match_flag),
        .frame_error_flag(frame_error_flag),
        .parity_error_flag(parity_error_flag),
        .overrun_flag(overrun_flag),
        .timeout_flag(timeout_flag),
        .rx(rx),
        .tx(tx)
    );

    assign PRDATA =
        (PADDR[15:0] == RXDATA_OFF)      ? {{(32-MDW){1'b0}},rx_data} :
        (PADDR[15:0] == PR_OFF)         ? {{16{1'b0}},pr_reg} :
        (PADDR[15:0] == CTRL_OFF)       ? {{27{1'b0}},ctrl_reg} :
        (PADDR[15:0] == CFG_OFF)        ? {{18{1'b0}},cfg_reg} :
        (PADDR[15:0] == MATCH_OFF)      ? {{(32-MDW){1'b0}},match_reg} :
        (PADDR[15:0] == RX_LEVEL_OFF)   ? {{(32-FAW){1'b0}},rx_level} :
        (PADDR[15:0] == RX_THRESH_OFF)  ? {{(32-FAW){1'b0}},rx_thresh_reg} :
        (PADDR[15:0] == RX_FLUSH_OFF)   ? {31'd0,rx_flush_reg} :
        (PADDR[15:0] == TX_LEVEL_OFF)   ? {{(32-FAW){1'b0}},tx_level} :
        (PADDR[15:0] == TX_THRESH_OFF)  ? {{(32-FAW){1'b0}},tx_thresh_reg} :

