        if (!PRESETn) CMPX_REG <= 32'd0;
        else if (apb_we && (PADDR[15:0] == CMPX_REG_OFFSET))
            CMPX_REG <= PWDATA;

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) CMPY_REG <= 32'd0;
        else if (apb_we && (PADDR[15:0] == CMPY_REG_OFFSET))
            CMPY_REG <= PWDATA;

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) CTRL_REG <= 7'd0;
        else if (apb_we && (PADDR[15:0] == CTRL_REG_OFFSET))
            CTRL_REG <= PWDATA[6:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) CFG_REG <= 3'd0;
        else if (apb_we && (PADDR[15:0] == CFG_REG_OFFSET))
            CFG_REG <= PWDATA[2:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) PWM0CFG_REG <= 12'd0;
        else if (apb_we && (PADDR[15:0] == PWM0CFG_REG_OFFSET))
            PWM0CFG_REG <= PWDATA[11:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) PWM1CFG_REG <= 16'd0;
        else if (apb_we && (PADDR[15:0] == PWM1CFG_REG_OFFSET))
            PWM1CFG_REG <= PWDATA[15:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) PWMDT_REG <= 8'd0;
        else if (apb_we && (PADDR[15:0] == PWMDT_REG_OFFSET))
            PWMDT_REG <= PWDATA[7:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) PWMFC_REG <= 16'd0;
        else if (apb_we && (PADDR[15:0] == PWMFC_REG_OFFSET))
            PWMFC_REG <= PWDATA[15:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) GCLK_REG <= 1'b0;
        else if (apb_we && (PADDR[15:0] == GCLK_REG_OFFSET))
            GCLK_REG <= PWDATA[0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) IM_REG <= 3'd0;
        else if (apb_we && (PADDR[15:0] == IM_REG_OFFSET))
            IM_REG <= PWDATA[2:0];

    always @(posedge PCLK or negedge PRESETn)
        if (!PRESETn) IC_REG <= 3'd0;
        else if (apb_we && (PADDR[15:0] == IC_REG_OFFSET))
            IC_REG <= PWDATA[2:0];
        else
            IC_REG <= 3'd0;

    always @(posedge PCLK or negedge PRESETn) begin
        if (!PRESETn)
            RIS_REG <= 3'd0;
        else begin
            if (IC_REG[0])
                RIS_REG[0] <= 1'b0;
            else if (timeout_flag)
                RIS_REG[0] <= 1'b1;

            if (IC_REG[1])
                RIS_REG[1] <= 1'b0;
            else if (matchx_flag)
                RIS_REG[1] <= 1'b1;

            if (IC_REG[2])
                RIS_REG[2] <= 1'b0;
            else if (matchy_flag)
                RIS_REG[2] <= 1'b1;
        end
    end

    /*
     * GCLK is intentionally stored only.  The clock gate is a plain wire
     * in this build, so it has no effect on timer operation.
     */
    EF_TMR32 #(.PRW(PRW)) instance_to_wrap (
        .clk(PCLK),
        .rst_n(PRESETn),
        .tmr_en(CTRL_REG[0]),
        .tmr_start(CTRL_REG[1]),
        .pwm0_en(CTRL_REG[2]),
        .pwm1_en(CTRL_REG[3]),
        .tmr_reload(RELOAD_REG),
        .cmpx(CMPX_REG),
        .cmpy(CMPY_REG),
        .prescaler(PR_REG),
        .tmr_cfg(CFG_REG),
        .pwm0_cfg(PWM0CFG_REG),
        .pwm1_cfg(PWM1CFG_REG[11:0]),
        .pwm0_inv(CTRL_REG[5]),
        .pwm1_inv(CTRL_REG[6]),
        .pwm_dt(PWMDT_REG),
