        .pwm_dt_en(CTRL_REG[4]),
        .tmr(tmr),
        .matchx_flag(matchx_flag),
        .matchy_flag(matchy_flag),
        .timeout_flag(timeout_flag),
        .pwm0(pwm0),
        .pwm1(pwm1),
        .pwm_fault(pwm_fault[0])
    );

    assign PRDATA =
        (PADDR[15:0] == TMR_REG_OFFSET)     ? tmr :
        (PADDR[15:0] == RELOAD_REG_OFFSET)  ? RELOAD_REG :
